#!/usr/bin/env python3
"""HistoryIT diagnostics repair 2026-10-06-1; run from the project root."""
from pathlib import Path
import base64, gzip, io, os, shutil, tarfile, tempfile, time
VERSION = '2026-10-06-1'
PAYLOAD = ''

def find_target(cwd):
    candidates=[cwd,cwd/'history-it-project',cwd/'HitoryIT'/'history-it-project',cwd/'historyit-archive-mvp']
    found=[p for p in candidates if (p/'app'/'inspection.py').is_file() and (p/'app'/'main.py').is_file()]
    if not found: raise SystemExit('No HistoryIT project found. Put this script inside history-it-project and run it there.')
    if len(found)>1: raise SystemExit('Multiple projects found. Put this script inside the exact project served by Uvicorn and run it there.')
    return found[0].resolve()

def verify(target):
    checks={'app/main.py':"DIAGNOSTICS_BUILD='2026-10-06-1'",
            'app/inspection.py':'from app.diagnostics import Diagnostics',
            'app/orchestrator.py':"'inspection_attempt': attempt",
            'app/config.py':"diagnostics_dir: str = './logs'"}
    for name,marker in checks.items():
        if marker not in (target/name).read_text(encoding='utf-8'):
            raise SystemExit(f'INSTALLATION FAILED: {name} does not have the {VERSION} marker')
    if not (target/'app'/'diagnostics.py').is_file():
        raise SystemExit('INSTALLATION FAILED: app/diagnostics.py missing')
    print(f'VERIFIED diagnostics build {VERSION} in {target}')
    print('Before any OpenAI retry, restart Uvicorn and GET /health; diagnostics_build must equal '+VERSION)
    print('Future attempt files will be under '+str((target/'logs').resolve()))

def main():
    target=find_target(Path.cwd().resolve())
    backup=target.parent/(target.name+'.diagnostics_backup_'+time.strftime('%Y%m%d_%H%M%S'))
    backup.mkdir(parents=True,exist_ok=False)
    print('TARGET PROJECT:',target)
    with tempfile.TemporaryDirectory(prefix='historyit_diagnostics_') as directory:
        unpack=Path(directory)
        with tarfile.open(fileobj=io.BytesIO(gzip.decompress(base64.b64decode(PAYLOAD))),mode='r:') as tar:
            try: tar.extractall(unpack,filter='data')
            except TypeError: tar.extractall(unpack)
        for src in (p for p in unpack.rglob('*') if p.is_file()):
            rel=src.relative_to(unpack); dst=target/rel
            if dst.exists():
                prior=backup/rel; prior.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(dst,prior)
            dst.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(src,dst)
    print('BACKUP:',backup)
    verify(target)
if __name__=='__main__': main()
